arguments.file_text:
@page "/board"
@using sv_caeb8f4f753845a88e99dd942f29f2e4.Components.Pages.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

@if (isLoading)
{
    <p class="loading-message">Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <p class="error-message">@errorMessage</p>
}
else
{
    <BoardStats Tasks="tasks" />

    <TaskSearch SearchText="@searchText" SearchTextChanged="OnSearchChanged" />

    <div class="kanban-board">
        <KanbanColumn Title="To Do" Status="To Do"
                      Tasks="GetFilteredTasks("To Do")"
                      ShowMoveLeft="false" ShowMoveRight="true"
                      OnMoveRight="MoveRight"
                      OnTaskAdd="HandleAddTask" />

        <KanbanColumn Title="In Progress" Status="In Progress"
                      Tasks="GetFilteredTasks("In Progress")"
                      ShowMoveLeft="true" ShowMoveRight="true"
                      OnMoveLeft="MoveLeft" OnMoveRight="MoveRight"
                      OnTaskAdd="HandleAddTask" />

        <KanbanColumn Title="Done" Status="Done"
                      Tasks="GetFilteredTasks("Done")"
                      ShowMoveLeft="true" ShowMoveRight="false"
                      OnMoveLeft="MoveLeft"
                      OnTaskAdd="HandleAddTask" />
    </div>
}

@code {
    private List<TaskItem> tasks = new();
    private string searchText = "";
    private bool isLoading = true;
    private string? errorMessage;

    private static readonly string[] Statuses = { "To Do", "In Progress", "Done" };

    protected override async Task OnInitializedAsync()
    {
        try
        {
            tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var filtered = tasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            filtered = filtered.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }
        return filtered.ToList();
    }

    private void OnSearchChanged(string value)
    {
        searchText = value;
    }

    private async Task MoveLeft(int taskId)
    {
        var task = tasks.FirstOrDefault(t => t.Id == taskId);
        if (task is null) return;

        var currentIndex = Array.IndexOf(Statuses, task.Status);
        if (currentIndex <= 0) return;

        var newStatus = Statuses[currentIndex - 1];
        await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
        UpdateLocalTaskStatus(taskId, newStatus);
    }

    private async Task MoveRight(int taskId)
    {
        var task = tasks.FirstOrDefault(t => t.Id == taskId);
        if (task is null) return;

        var currentIndex = Array.IndexOf(Statuses, task.Status);
        if (currentIndex >= Statuses.Length - 1) return;

        var newStatus = Statuses[currentIndex + 1];
        await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
        UpdateLocalTaskStatus(taskId, newStatus);
    }

    private void UpdateLocalTaskStatus(int taskId, string newStatus)
    {
        var index = tasks.FindIndex(t => t.Id == taskId);
        if (index >= 0)
        {
            var old = tasks[index];
            tasks[index] = old with { Status = newStatus };
        }
    }

    private async Task HandleAddTask(AddTaskForm.NewTaskModel model)
    {
        var newTask = await TaskService.CreateTaskAsync(model.Title, model.Assignee, model.Priority, model.DueDate);
        tasks.Add(newTask);
    }
}

